"""Text-to-SQL harness: draft -> execute -> optional data-grounded repair.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}
  env.chat(messages, max_tokens=None) -> str     capped per task (env.max_calls)
  env.schema(db_id) -> str
  env.execute(sql, max_rows=20) -> dict          {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str
  env.prompt(name) -> str
  env.config -> dict
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
IDENT = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
STR_LIT = re.compile(r"'((?:[^']|'')*)'")


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    t = (text or "").strip()
    # fall back to the last statement-looking line if prose surrounds it
    m = re.search(r"(?is)\b(select|with)\b.*", t)
    if m:
        t = m.group(0)
    return t.strip().rstrip(";").strip()


def _tables(schema):
    """table name -> list of (column, declared type), from CREATE statements."""
    out = {}
    for m in re.finditer(
        r"CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?[\"'`\[]?([\w]+)[\"'`\]]?\s*\((.*?)\)\s*;",
        schema or "",
        re.S | re.I,
    ):
        name, body = m.group(1), m.group(2)
        cols = []
        depth = 0
        cur = ""
        parts = []
        for ch in body:
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
            if ch == "," and depth == 0:
                parts.append(cur)
                cur = ""
            else:
                cur += ch
        parts.append(cur)
        for p in parts:
            p = p.strip()
            if not p:
                continue
            first = p.split()[0].strip("\"'`[]")
            if first.upper() in ("PRIMARY", "FOREIGN", "UNIQUE", "CHECK", "CONSTRAINT"):
                continue
            typ = p[len(p.split()[0]):].strip().upper()
            cols.append((first, typ))
        out[name] = cols
    return out


def _probe(env, db_id, schema, sql, budget=6):
    """Sample real stored values for text columns the draft touches."""
    tabs = _tables(schema)
    used = set(IDENT.findall(sql or ""))
    lines = []
    for tname, cols in tabs.items():
        if tname not in used:
            continue
        text_cols = [c for c, ty in cols if ("CHAR" in ty or "TEXT" in ty or "CLOB" in ty or ty == "")]
        text_cols = [c for c in text_cols if c in used] or text_cols[:3]
        for c in text_cols[:3]:
            if len(lines) >= budget:
                break
            q = 'SELECT DISTINCT "%s" FROM "%s" WHERE "%s" IS NOT NULL LIMIT 8' % (c, tname, c)
            try:
                r = env.execute(q, max_rows=8)
            except Exception:
                continue
            if r.get("ok") and r.get("rows"):
                vals = [str(row[0]) for row in r["rows"]]
                lines.append("%s.%s sample values: %s" % (tname, c, " | ".join(vals)))
        if len(lines) >= budget:
            break
    return "\n".join(lines)


def _fmt_result(r):
    if not r.get("ok"):
        return "ERROR: %s" % r.get("error")
    if r.get("n_rows", 0) == 0:
        return "0 rows returned."
    head = ", ".join(map(str, r.get("columns") or []))
    rows = "; ".join(str(row) for row in (r.get("rows") or [])[:5])
    return "%d rows. columns: [%s]. first rows: %s" % (r.get("n_rows", 0), head, rows)


def _rowkey(x):
    try:
        hash(x)
        return x
    except Exception:
        return repr(x)


def _dup_report(res):
    """Describe repeated result rows (join fan-out); None when there are none."""
    rows = res.get("rows") or []
    if len(rows) < 2:
        return None
    keys = []
    for r in rows:
        try:
            keys.append(tuple(_rowkey(v) for v in r))
        except Exception:
            return None
    seen = {}
    order = []
    for k in keys:
        if k not in seen:
            seen[k] = 0
            order.append(k)
        seen[k] += 1
    dups = [(k, seen[k]) for k in order if seen[k] > 1]
    if not dups:
        return None
    extra = sum(c - 1 for _, c in dups)
    shown = "; ".join("%s x%d" % (list(k), c) for k, c in dups[:3])
    return (
        "%d of the %d sampled rows are exact repeats (%d distinct rows). Repeated rows: %s. "
        "Repeats usually mean a one-to-many join multiplied the rows." % (extra, len(rows), len(order), shown)
    )


def _split_top(s):
    parts, depth, cur, quote = [], 0, "", None
    for ch in s:
        if quote:
            cur += ch
            if ch == quote:
                quote = None
            continue
        if ch in "'\"`":
            quote = ch
            cur += ch
            continue
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        if ch == "," and depth == 0:
            parts.append(cur)
            cur = ""
        else:
            cur += ch
    parts.append(cur)
    return parts


def _top_keyword(sql, kw):
    """Index of a top-level keyword outside strings/parens, else -1."""
    depth, quote, i, n = 0, None, 0, len(sql)
    up = sql.upper()
    while i < n:
        ch = sql[i]
        if quote:
            if ch == quote:
                quote = None
            i += 1
            continue
        if ch in "'\"`":
            quote = ch
            i += 1
            continue
        if ch == "(":
            depth += 1
            i += 1
            continue
        if ch == ")":
            depth -= 1
            i += 1
            continue
        if depth == 0 and up.startswith(kw, i):
            before_ok = i == 0 or not (sql[i - 1].isalnum() or sql[i - 1] == "_")
            j = i + len(kw)
            after_ok = j >= n or not (sql[j].isalnum() or sql[j] == "_")
            if before_ok and after_ok:
                return i
        i += 1
    return -1


def _select_parts(sql):
    """(start, end, items) of the outer SELECT list, or None."""
    s = sql.strip()
    if not re.match(r"(?is)^select\b", s):
        return None
    start = len("SELECT")
    distinct = False
    m = re.match(r"(?is)\s+(distinct|all)\b", s[start:])
    if m:
        distinct = m.group(1).lower() == "distinct"
        start += m.end()
    end = _top_keyword(s, "FROM")
    if end < 0:
        end = len(s)
    items = [p.strip() for p in _split_top(s[start:end]) if p.strip()]
    return start, end, items, distinct


def _variants(env, sql, res):
    """Executed, evidence-backed alternatives: dedup and wider projection."""
    out = []
    parts = _select_parts(sql)
    if parts is None:
        return out
    start, end, items, distinct = parts
    body = sql[end:]

    if not distinct and _dup_report(res):
        alt = sql[:start] + " DISTINCT" + sql[start:end] + body
        try:
            r = env.execute(alt, max_rows=20)
        except Exception:
            r = None
        if r and r.get("ok"):
            out.append(
                "Variant A (same query with DISTINCT):\n```sql\n%s\n```\nexecuted -> %s"
                % (alt, _fmt_result(r))
            )

    # Wider projection: when the draft names only a couple of plain columns of one
    # table, show what returning that whole entity's rows looks like.
    if len(items) <= 3 and not any("(" in it or "*" in it for it in items):
        refs = []
        for it in items:
            m = re.match(r'^([A-Za-z_]\w*)\s*\.\s*"?([A-Za-z_]\w*)"?$', it)
            if m:
                refs.append(m.group(1))
            elif re.match(r'^"?[A-Za-z_]\w*"?$', it):
                refs.append(None)
            else:
                refs = []
                break
        if refs:
            named = set(x for x in refs if x)
            alias = sorted(named)[0] if len(named) == 1 else None
            if alias is None and all(x is None for x in refs):
                fm = re.match(r'(?is)\s*from\s+"?([A-Za-z_]\w*)"?', body)
                alias = fm.group(1) if fm else None
            if alias:
                alt = "SELECT %s.*%s" % (alias, body)
                try:
                    r = env.execute(alt, max_rows=5)
                except Exception:
                    r = None
                if r and r.get("ok") and r.get("n_rows", 0) > 0:
                    label = "Variant B" if out else "Variant A"
                    out.append(
                        "%s (all columns of the main entity instead of the narrow projection):\n"
                        "```sql\n%s\n```\nexecuted -> %s" % (label, alt, _fmt_result(r))
                    )
    return out


def solve(task, env):
    db_id = task["db_id"]
    schema = env.schema(db_id)
    user = "Database: %s\n\nSchema:\n%s\n\nQuestion: %s" % (db_id, schema, task["question"])
    if task.get("hint"):
        user += "\nHint: %s" % task["hint"]
    desc = ""
    try:
        desc = env.descriptions(db_id) or ""
    except Exception:
        pass
    if desc.strip():
        user += "\n\nColumn descriptions:\n" + desc.strip()[:2000]

    sys_msg = {"role": "system", "content": env.prompt("system_prompt.md")}
    messages = [sys_msg, {"role": "user", "content": user}]
    reply = env.chat(messages, max_tokens=env.config.get("max_tokens", 800))
    sql = extract_sql(reply)

    max_calls = getattr(env, "max_calls", 1) or 1
    if max_calls < 2:
        return {"sql": sql}

    try:
        res = env.execute(sql, max_rows=20)
    except Exception:
        return {"sql": sql}

    ok = bool(res.get("ok"))
    empty = ok and res.get("n_rows", 0) == 0
    dup = _dup_report(res) if ok else None
    if ok and not empty and not dup:
        return {"sql": sql}

    feedback = "Your query was executed on the real database.\nResult: %s\n" % _fmt_result(res)

    if not ok or empty:
        probe = _probe(env, db_id, schema, sql)
        if probe:
            feedback += "\nActual stored values (use these exact spellings/cases):\n%s\n" % probe
        lits = [s for s in STR_LIT.findall(sql) if s]
        if lits:
            feedback += "\nString literals you used: %s\n" % ", ".join(repr(x) for x in lits[:8])
        feedback += (
            "\nThe query is probably wrong: check exact literal spellings/case, which column really "
            "holds the value, join keys and direction, and whether a filter should be case-insensitive "
            "or a LIKE pattern. Also reconsider the projected columns if the question asks about whole "
            "entities rather than one attribute. If you are confident the empty result is genuinely "
            "correct, return the same query.\n"
        )
    else:
        feedback += "\nObservation: %s\n" % dup
        feedback += (
            "\nDecide from the question wording: if it asks for each entity once (names, list of X, "
            "everybody who ...), collapse the fan-out with DISTINCT; if it legitimately asks for one row "
            "per related record, keep the duplicates. Also check the projection width: questions that "
            "name an entity without naming attributes usually want that entity's columns, not just a name.\n"
        )

    for v in _variants(env, sql, res):
        feedback += "\n" + v + "\n"
    feedback += (
        "\nReturn the single best final query in one ```sql block (it may be your original, a variant, "
        "or your own correction). No commentary."
    )

    messages = messages + [
        {"role": "assistant", "content": reply},
        {"role": "user", "content": feedback},
    ]
    try:
        reply2 = env.chat(messages, max_tokens=env.config.get("max_tokens", 800))
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    try:
        res2 = env.execute(sql2, max_rows=20)
    except Exception:
        return {"sql": sql}
    if not res2.get("ok"):
        return {"sql": sql}
    return {"sql": sql2}

proposal.raw:
**Diagnosis.** All three current failures share one shape: the query *executes fine and returns rows*, so the incumbent's repair trigger (`error or 0 rows`) never fires. Two sub-patterns: (a) join fan-out duplicates — sp0536 returns 8 rows where gold has 5, sp0600 returns `music` twice; (b) projection width — sp0755 projects `Name` while gold projects all joined columns. The prompt already says "return all columns" for entity questions, yet the model still narrows to `Name`, so a prompt-only fix is weak; a data-grounded second call that *shows* the duplication and the full-row alternative is stronger.

**Edit.** Generalize the repair trigger from "empty/error" to "empty/error **or** duplicate result rows", feed the policy the observed duplicate groups plus an executed `SELECT DISTINCT` variant (and, when the draft projects a narrow subset, an executed `SELECT <alias>.*` variant), and let it pick. Add one prompt rule tying "everybody/all/which X that have relationship Y" to DISTINCT. No task-, db- or table-specific logic: everything is derived from the returned rows and the draft's own aliases.

